{
  "findings": [
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket is not encrypted with KMS by default, potentially exposing stored data."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have versioning enabled, which could lead to data loss or corruption."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket lacks a Public Access block, potentially allowing unauthorized public access."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.changeme_aws_s3_bucket_backend_simple",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have access logging enabled, making it difficult to track access and changes."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "changeme_aws_s3_bucket_backend_simple" {
  force_destroy = true
  bucket        = "changeme-${random_id.changeme_backends_s3_bucket_name.hex}"
}

resource "aws_s3_bucket_versioning" "changeme_aws_s3_bucket_backend_simple_versioning" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "changeme_aws_s3_bucket_backend_simple_encryption" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_kms_key" "s3" {
  description             = "KMS key for S3 encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket_public_access_block" "changeme_aws_s3_bucket_backend_simple_public_access_block" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id

  block_public_acls   = true
  block_public_policy = true
  ignore_public_acls  = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "changeme_aws_s3_bucket_backend_simple_logging" {
  bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id

  target_bucket = aws_s3_bucket.changeme_aws_s3_bucket_backend_simple.id
  target_prefix = "logs/"
}",
  "fix_summary": "Enabled S3 bucket versioning, encryption with KMS, public access block, and access logging to address identified security misconfigurations."
}
